insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual regra vale para todas as palavras proparoxítonas?','Todas as proparoxítonas são acentuadas graficamente.','Gramática normativa',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='portugues' and t.name='Emprego da acentuação gráfica.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'A vírgula pode separar diretamente o sujeito do verbo?','Em regra, não. Sujeito e predicado não devem ser separados por vírgula.','Gramática normativa',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='portugues' and t.name='Emprego dos sinais de pontuação.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Como se flexiona o verbo “haver” com sentido de existir?','É impessoal e fica na 3ª pessoa do singular: “Havia problemas”.','Gramática normativa',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='portugues' and t.name='Concordância nominal e verbal.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual a função dos conectivos em um texto?','Articular ideias e explicitar relações como causa, oposição, conclusão e condição.','Coesão textual',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='portugues' and t.name='Domínio dos mecanismos de coesão textual.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a negação de “P e Q”?','“Não P ou não Q” (¬P ∨ ¬Q).','Leis de De Morgan',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='rlm' and t.name='Leis de De Morgan.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'A proposição “P → Q” é equivalente a quê?','À disjunção “¬P ∨ Q”.','Lógica proposicional',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='rlm' and t.name='Equivalências lógicas.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a fórmula da combinação de n elementos tomados p a p?','C(n,p) = n! / [p!(n−p)!].','Análise combinatória',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='rlm' and t.name='Permutações, arranjos e combinações.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Aumentar 10% e depois reduzir 10% retorna ao valor inicial?','Não. O resultado é 99% do valor inicial, pois 1,10 × 0,90 = 0,99.','Porcentagem',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='rlm' and t.name='Porcentagem e variações percentuais.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Como é calculada a média aritmética simples?','Soma-se todos os valores e divide-se pela quantidade de observações.','Estatística descritiva',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='estatistica' and t.name='Medidas de posição: média aritmética, mediana, moda, quartis, decis e percentis.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que é a mediana?','O valor central dos dados ordenados; com número par de dados, usa-se a média dos dois centrais.','Estatística descritiva',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='estatistica' and t.name='Medidas de posição: média aritmética, mediana, moda, quartis, decis e percentis.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a fórmula de P(A|B), com P(B)>0?','P(A|B) = P(A∩B) / P(B).','Probabilidade condicional',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='estatistica' and t.name='Probabilidade condicional.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Correlação estatística prova relação de causa e efeito?','Não. Correlação indica associação; causalidade exige evidências adicionais.','Análise de dados',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='estatistica' and t.name='Correlação e causalidade.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a equação fundamental do patrimônio?','Ativo = Passivo + Patrimônio Líquido.','Contabilidade geral',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='contabilidade' and t.name='Equação fundamental do patrimônio.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Como, em regra, aumenta uma conta do Ativo?','Por lançamento a débito; contas do Ativo têm natureza devedora, salvo contas retificadoras.','Contabilidade geral',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='contabilidade' and t.name='Débito, crédito e saldo.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quando receitas e despesas são reconhecidas no regime de competência?','No período em que são geradas ou incorridas, independentemente do pagamento ou recebimento.','Contabilidade geral',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='contabilidade' and t.name='Regime de competência.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O Balanço Patrimonial mostra posição ou desempenho ao longo do período?','Posição patrimonial e financeira em determinada data.','Contabilidade geral',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='contabilidade' and t.name='Balanço patrimonial: conceito, estrutura e composição.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que significa confidencialidade na segurança da informação?','Garantir que a informação seja acessada apenas por pessoas ou sistemas autorizados.','Segurança da informação',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='informatica' and t.name='Segurança da informação e segurança cibernética: confidencialidade, integridade, disponibilidade, autenticidade e rastreabilidade das informações.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que significa integridade da informação?','Preservar a exatidão e impedir alterações não autorizadas nos dados.','Segurança da informação',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='informatica' and t.name='Segurança da informação e segurança cibernética: confidencialidade, integridade, disponibilidade, autenticidade e rastreabilidade das informações.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a diferença entre autenticação e autorização?','Autenticação confirma quem é o usuário; autorização define o que ele pode acessar ou fazer.','Segurança da informação',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='informatica' and t.name='Autenticação.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que é phishing?','Fraude de engenharia social que tenta induzir a vítima a revelar dados ou executar ações maliciosas.','Segurança cibernética',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='informatica' and t.name='Phishing.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que estabelece o art. 1º do Código Penal?','Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.','Código Penal, art. 1º',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='penal' and t.name='Princípios fundamentais do Direito Penal.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quando o crime é considerado tentado?','Quando a execução é iniciada, mas o crime não se consuma por circunstâncias alheias à vontade do agente.','Código Penal, art. 14, II',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='penal' and t.name='Consumação e tentativa.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quando o crime é doloso segundo o Código Penal?','Quando o agente quis o resultado ou assumiu o risco de produzi-lo.','Código Penal, art. 18, I',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='penal' and t.name='Dolo e culpa.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual regra geral o art. 29 do Código Penal traz para quem concorre para o crime?','Incide nas penas cominadas ao crime, na medida de sua culpabilidade.','Código Penal, art. 29',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='penal' and t.name='Concurso de pessoas.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual lei realmente dispõe sobre a tipificação criminal de delitos informáticos?','Lei nº 12.737/2012. O edital PC/AP grafou 12.727/2012 nesse ponto.','Edital PC/AP 2026; Lei nº 12.737/2012',3 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='penal' and t.name='Lei nº 12.727/2012 – Tipificação criminal de delitos informáticos.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a finalidade do inquérito policial?','Apurar a infração penal e sua autoria para subsidiar a persecução penal.','CPP, art. 4º',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='processo-penal' and t.name='Inquérito policial.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quando a infração deixa vestígios, a confissão substitui o exame de corpo de delito?','Não. O exame de corpo de delito é indispensável e a confissão não o supre.','CPP, art. 158',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='processo-penal' and t.name='Exame de corpo de delito e perícias.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que é cadeia de custódia?','Conjunto de procedimentos para manter e documentar a história cronológica do vestígio, do reconhecimento ao descarte.','CPP, art. 158-A',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='processo-penal' and t.name='Cadeia de custódia da prova.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quais são as quatro situações de flagrante do art. 302 do CPP?','Cometer; acabar de cometer; ser perseguido logo após; ou ser encontrado logo depois com elementos que façam presumir autoria.','CPP, art. 302',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='processo-penal' and t.name='Prisão em flagrante.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que diz a legalidade do art. 5º, II, da Constituição?','Ninguém será obrigado a fazer ou deixar de fazer algo senão em virtude de lei.','CF, art. 5º, II',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='constitucional' and t.name='Princípio da legalidade.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Em quais hipóteses alguém pode entrar em casa alheia sem consentimento do morador?','Flagrante delito, desastre, prestação de socorro ou, durante o dia, por determinação judicial.','CF, art. 5º, XI',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='constitucional' and t.name='Inviolabilidade domiciliar.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual direito é protegido pelo habeas corpus?','A liberdade de locomoção diante de violência ou coação ilegal, efetiva ou ameaçada.','CF, art. 5º, LXVIII',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='constitucional' and t.name='Habeas corpus.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual função constitucional cabe às polícias civis?','Funções de polícia judiciária e apuração de infrações penais, exceto as militares, ressalvada a competência da União.','CF, art. 144, §4º',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='constitucional' and t.name='Polícias Civis.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quais são os princípios expressos no caput do art. 37 da Constituição?','Legalidade, impessoalidade, moralidade, publicidade e eficiência (LIMPE).','CF, art. 37, caput',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='administrativo' and t.name='Administração Pública: conceito e princípios.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual a diferença central entre anulação e revogação do ato administrativo?','Anulação combate ilegalidade; revogação retira ato válido por conveniência e oportunidade.','Direito Administrativo',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='administrativo' and t.name='Anulação e revogação.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que caracteriza o poder de polícia administrativa?','A atividade estatal que condiciona ou restringe direitos e atividades em favor do interesse público.','Direito Administrativo',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='administrativo' and t.name='Poder de polícia.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a regra constitucional para a responsabilidade civil das pessoas jurídicas estatais por atos de seus agentes?','Responsabilidade objetiva pelos danos causados a terceiros, assegurado regresso contra o agente em caso de dolo ou culpa.','CF, art. 37, §6º',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='administrativo' and t.name='Responsabilidade civil do Estado.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Em que data a Declaração Universal dos Direitos Humanos foi adotada pela ONU?','10 de dezembro de 1948.','DUDH',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='direitos-humanos' and t.name='Declaração Universal dos Direitos Humanos.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual ideia central orienta a igualdade na DUDH?','Todos nascem livres e iguais em dignidade e direitos e devem gozar direitos sem discriminação.','DUDH, arts. 1º e 2º',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='direitos-humanos' and t.name='Igualdade e não discriminação.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'A proibição da tortura admite justificativa por circunstância excepcional?','Não. Guerra, instabilidade política ou outra emergência não justificam a tortura.','Convenção contra a Tortura, art. 2º',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='direitos-humanos' and t.name='Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quais critérios devem orientar o uso da força na atividade policial segundo o edital?','Legalidade, necessidade, proporcionalidade e responsabilização.','Edital PC/AP 2026',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='direitos-humanos' and t.name='Legalidade, necessidade, proporcionalidade e responsabilização no uso da força.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quais países disputaram a região do Contestado no norte do atual Amapá?','Brasil e França.','História do Amapá',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='historia-ap' and t.name='Contestado franco-brasileiro.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Em que ano o Laudo Suíço resolveu o Contestado em favor do Brasil?','1900.','Laudo Suíço, Genebra, 1900',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='historia-ap' and t.name='Laudo Suíço.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Em que ano foi criado o Território Federal do Amapá?','1943.','Decreto-Lei nº 5.812/1943',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='historia-ap' and t.name='Criação do Território Federal do Amapá.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual marco transformou o Amapá de Território Federal em Estado?','A Constituição Federal de 1988.','CF/1988, ADCT, art. 14',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='historia-ap' and t.name='Transformação do Amapá em Estado.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual é a capital do Estado do Amapá?','Macapá.','IBGE',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='geografia-ap' and t.name='Localização geográfica e limites territoriais.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quantos municípios possui o Estado do Amapá?','16 municípios.','IBGE',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='geografia-ap' and t.name='Divisão político-administrativa e municípios.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Com qual território estrangeiro o Amapá possui fronteira internacional?','Com a Guiana Francesa, departamento ultramarino da França.','Geografia do Amapá',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='geografia-ap' and t.name='Fronteira internacional e faixa de fronteira.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual linha imaginária atravessa a região de Macapá?','A Linha do Equador.','IBGE / Geografia do Amapá',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='geografia-ap' and t.name='Localização geográfica e limites territoriais.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'O que a Lei nº 14.735/2023 institui?','A Lei Orgânica Nacional das Polícias Civis e normas gerais de funcionamento dessas instituições.','Lei nº 14.735/2023, art. 1º',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='legislacao' and t.name='Lei nº 14.735/2023 — Lei Orgânica Nacional das Polícias Civis.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quais cargos integram o quadro policial previsto na Lei Orgânica Nacional?','Delegado de polícia, oficial investigador de polícia e perito oficial criminal.','Lei nº 14.735/2023, art. 19',1 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='legislacao' and t.name='Organização básica das Polícias Civis.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Quais núcleos de atribuição do oficial investigador aparecem no art. 27 da Lei nº 14.735/2023?','Atividades apuratórias, cartorárias, procedimentais, obtenção de dados, inteligência e ações investigativas.','Lei nº 14.735/2023, art. 27',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='legislacao' and t.name='Atribuições do Oficial Investigador de Polícia.' on conflict (topic_id,front) do nothing;
insert into public.flashcards (topic_id,front,back,reference,difficulty) select t.id,'Qual competência central da Polícia Civil aparece no art. 6º da Lei nº 14.735/2023?','Executar privativamente polícia judiciária civil e apuração de infrações penais, ressalvadas União e infrações militares.','Lei nº 14.735/2023, art. 6º',2 from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='legislacao' and t.name='Princípios, diretrizes e competências.' on conflict (topic_id,front) do nothing;
